import type { NextConfig } from 'next'

const nextConfig: NextConfig = {
  cacheComponents: true,
}

export default nextConfig

import { cookies } from 'next/headers'
import { cacheLife } from 'next/cache'

async function CartSummary() {
  'use cache'
  cacheLife('hours')

  const cartId = (await cookies()).get('cart')?.value
  const items = await getCartItems(cartId)

  return <p>Товаров: {items.length}</p>
}

async function Component({ userId }: { userId: string }) {
  const getData = async (filter: string) => {
    'use cache'
    const res = await fetch(
      `https://api.example.com/users/${userId}/data?filter=${filter}`
    )
    return res.json()
  }

  return getData('active')
}

export async function getData() {
  'use cache'
  // cacheLife не вызван
  const res = await fetch('https://api.example.com/data')
  return res.json()
}

import { cacheLife } from 'next/cache'

export async function getTicker() {
  'use cache'
  cacheLife({ stale: 5 })
  return fetch('https://api.example.com/ticker').then((r) => r.json())
}

async function LatestPosts() {
  const data = await fetch('https://api.example.com/posts')
  const posts = await data.json()
  return <ul>{posts.map((p) => <li key={p.id}>{p.title}</li>)}</ul>
}

export default function Page() {
  return (
    <>
      <h1>Блог</h1>
      <LatestPosts />
    </>
  )
}

